from pathlib import Path
out = Path('/app/output')
for p in out.iterdir():
    if p.name == 'gen.py':
        continue
    if p.is_dir():
        import shutil
        shutil.rmtree(p)
    else:
        p.unlink()
print('remaining:', [p.name for p in out.iterdir()])
